use pyo3::exceptions::PyValueError;
use pyo3::prelude::*;
use pyo3::types::PyList;

#[pyfunction]
fn total_and_mark(values: &Bound<'_, PyList>) -> PyResult<i64> {
    let mut total = 0_i64;
    for value in values.iter() {
        total += value.extract::<i64>()?;
    }
    values.append(total)?;
    if total < 0 {
        return Err(PyValueError::new_err("negative total"));
    }
    Ok(total)
}

